namespace RonSijm.FluidHumidifier.Factories.DevOpsAgent;

public class InnerAssociationServiceConfigurationFactory(Action<Humidifier.DevOpsAgent.AssociationTypes.ServiceConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.DevOpsAgent.AssociationTypes.ServiceConfiguration>
{

    internal InnerAssociationMCPServerConfigurationFactory MCPServerFactory { get; set; }

    internal InnerAssociationServiceNowConfigurationFactory ServiceNowFactory { get; set; }

    internal InnerAssociationAzureConfigurationFactory AzureFactory { get; set; }

    internal InnerAssociationGitHubConfigurationFactory GitHubFactory { get; set; }

    internal InnerAssociationMCPServerGrafanaConfigurationFactory MCPServerGrafanaFactory { get; set; }

    internal InnerAssociationMCPServerSplunkConfigurationFactory MCPServerSplunkFactory { get; set; }

    internal InnerAssociationMCPServerNewRelicConfigurationFactory MCPServerNewRelicFactory { get; set; }

    internal InnerAssociationPagerDutyConfigurationFactory PagerDutyFactory { get; set; }

    internal InnerAssociationEventChannelConfigurationFactory EventChannelFactory { get; set; }

    internal InnerAssociationSourceAwsConfigurationFactory SourceAwsFactory { get; set; }

    internal InnerAssociationSlackConfigurationFactory SlackFactory { get; set; }

    internal InnerAssociationMCPServerDatadogConfigurationFactory MCPServerDatadogFactory { get; set; }

    internal InnerAssociationDynatraceConfigurationFactory DynatraceFactory { get; set; }

    internal InnerAssociationMCPServerSigV4ConfigurationFactory MCPServerSigV4Factory { get; set; }

    internal InnerAssociationAWSConfigurationFactory AwsFactory { get; set; }

    internal InnerAssociationGitLabConfigurationFactory GitLabFactory { get; set; }

    protected override Humidifier.DevOpsAgent.AssociationTypes.ServiceConfiguration Create()
    {
        var serviceConfigurationResult = CreateServiceConfiguration();
        factoryAction?.Invoke(serviceConfigurationResult);

        return serviceConfigurationResult;
    }

    private Humidifier.DevOpsAgent.AssociationTypes.ServiceConfiguration CreateServiceConfiguration()
    {
        var serviceConfigurationResult = new Humidifier.DevOpsAgent.AssociationTypes.ServiceConfiguration();

        return serviceConfigurationResult;
    }
    public override void CreateChildren(Humidifier.DevOpsAgent.AssociationTypes.ServiceConfiguration result)
    {
        base.CreateChildren(result);

        result.MCPServer ??= MCPServerFactory?.Build();
        result.ServiceNow ??= ServiceNowFactory?.Build();
        result.Azure ??= AzureFactory?.Build();
        result.GitHub ??= GitHubFactory?.Build();
        result.MCPServerGrafana ??= MCPServerGrafanaFactory?.Build();
        result.MCPServerSplunk ??= MCPServerSplunkFactory?.Build();
        result.MCPServerNewRelic ??= MCPServerNewRelicFactory?.Build();
        result.PagerDuty ??= PagerDutyFactory?.Build();
        result.EventChannel ??= EventChannelFactory?.Build();
        result.SourceAws ??= SourceAwsFactory?.Build();
        result.Slack ??= SlackFactory?.Build();
        result.MCPServerDatadog ??= MCPServerDatadogFactory?.Build();
        result.Dynatrace ??= DynatraceFactory?.Build();
        result.MCPServerSigV4 ??= MCPServerSigV4Factory?.Build();
        result.Aws ??= AwsFactory?.Build();
        result.GitLab ??= GitLabFactory?.Build();
    }

} // End Of Class

